# Generated by Claude: one-shot DB init for the db-init service.
# Safe to run on every start: schema always (IF NOT EXISTS), seed only on a brand-new DB.
# Seed jobs are generated here instead of read from seed.sql, so the job count is configurable.
import json
import logging
import os
import random
import time
import config
import jsonlog

SQL_DIR = config.BASE_DIR.parent / "db"

SEED_JOBS = int(os.environ.get("SEED_JOBS", "300"))
SEED_POISON_RATE = float(os.environ.get("SEED_POISON_RATE", "0.03"))
SEED_MIN_SIMS = int(os.environ.get("SEED_MIN_SIMS", "2000000"))
SEED_MAX_SIMS = int(os.environ.get("SEED_MAX_SIMS", "10000000"))
N_PORTFOLIOS = 200


def make_jobs(n):
    """Build n job params dicts. Same settings give the same jobs every time."""
    rng = random.Random("minigrid-seed")
    jobs = []
    for i in range(n):
        params = {
            "portfolio_id": i % N_PORTFOLIOS + 1,
            "n_sims": rng.randint(SEED_MIN_SIMS, SEED_MAX_SIMS),
            "confidence": rng.choice([0.95, 0.975, 0.99]),
            "seed": 1000 + i,
        }
        # Poison jobs: run_var raises ValueError on these every time, so they
        # should fail 3 times and land in dlq.
        if rng.random() < SEED_POISON_RATE:
            if rng.random() < 0.5:
                params["confidence"] = 1.99
            else:
                params["n_sims"] = 0
        jobs.append(params)
    return jobs


def seed(con):
    jobs = make_jobs(SEED_JOBS)
    now_ms = int(time.time() * 1000)
    con.execute("BEGIN IMMEDIATE")
    con.executemany(
        "INSERT INTO jobs (created_at, params) VALUES (?, ?)",
        [(now_ms, json.dumps(p)) for p in jobs],
    )
    con.execute("COMMIT")
    poison = sum(1 for p in jobs if p["confidence"] >= 1 or p["n_sims"] < 1)
    total_sims = sum(p["n_sims"] for p in jobs)
    logging.info("seeded %d jobs (%d poison, %d total sims)", len(jobs), poison, total_sims)


if __name__ == "__main__":
    jsonlog.setup("db-init")
    existed = os.path.exists(config.DB_PATH)

    con = config.connect()
    con.executescript((SQL_DIR / "schema.sql").read_text())
    if existed:
        logging.info("db already initialized at %s, skipping seed", config.DB_PATH)
    else:
        seed(con)
        logging.info("new db at %s, schema created and seeded", config.DB_PATH)
    con.close()
